import{_ as e,o as l,c as a,a2 as o}from"./chunks/framework.CZGNF-7T.js";const f=JSON.parse('{"title":"대시보드 (Dashboard) 사용 매뉴얼","description":"","frontmatter":{},"headers":[],"relativePath":"intro/dashboard.md","filePath":"intro/dashboard.md","lastUpdated":1788540733000}'),d={name:"intro/dashboard.md"};function s(r,t,n,i,c,g){return l(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="대시보드-dashboard-사용-매뉴얼" tabindex="-1">대시보드 (Dashboard) 사용 매뉴얼 <a class="header-anchor" href="#대시보드-dashboard-사용-매뉴얼" aria-label="Permalink to &quot;대시보드 (Dashboard) 사용 매뉴얼&quot;">​</a></h1><blockquote><p><strong>IBS 대시보드</strong>는 프로젝트 진행 상황, 분양 및 계약 지표, 자금 흐름, 그리고 개인의 업무/회의 현황까지 시스템 내의 핵심 데이터를 한눈에 모니터링할 수 있는 <strong>개인 맞춤형 지능형 포털</strong>입니다.</p></blockquote><h2 id="_1-주요-기능-및-조작-방법" tabindex="-1">1. 주요 기능 및 조작 방법 <a class="header-anchor" href="#_1-주요-기능-및-조작-방법" aria-label="Permalink to &quot;1. 주요 기능 및 조작 방법&quot;">​</a></h2><h3 id="💡-위젯-설정-및-개인화-customization" tabindex="-1">💡 위젯 설정 및 개인화 (Customization) <a class="header-anchor" href="#💡-위젯-설정-및-개인화-customization" aria-label="Permalink to &quot;💡 위젯 설정 및 개인화 (Customization)&quot;">​</a></h3><ul><li><strong>위젯 추가/숨김</strong>: 화면 우측 상단의 <strong>[위젯 설정]</strong> 버튼을 클릭하여 우측 서랍(Drawer) 패널을 엽니다. 원하는 위젯의 스위치를 On/Off하여 대시보드에 즉시 배치하거나 숨길 수 있습니다.</li><li><strong>기본값으로 초기화</strong>: 위젯 배치가 복잡해지거나 기본 구성으로 되돌리고 싶다면, 설정 패널 하단의 <strong>[기본값으로 초기화]</strong> 버튼을 클릭합니다.</li></ul><h3 id="🧩-레이아웃-조작-drag-resize" tabindex="-1">🧩 레이아웃 조작 (Drag &amp; Resize) <a class="header-anchor" href="#🧩-레이아웃-조작-drag-resize" aria-label="Permalink to &quot;🧩 레이아웃 조작 (Drag &amp; Resize)&quot;">​</a></h3><ul><li><strong>위치 이동 (Drag)</strong>: 위젯 상단 타이틀 바 또는 여백을 마우스로 잡고 원하는 위치로 드래그하면 바둑판 격자 위에서 부드럽게 재정렬됩니다.</li><li><strong>크기 조절 (Resize)</strong>: 위젯 우측 하단 모서리를 마우스로 드래그하여 위젯의 가로(폭)와 세로(높이)를 자유롭게 조정할 수 있습니다.</li></ul><h3 id="☁️-계정-클라우드-자동-동기화-auto-sync" tabindex="-1">☁️ 계정 클라우드 자동 동기화 (Auto Sync) <a class="header-anchor" href="#☁️-계정-클라우드-자동-동기화-auto-sync" aria-label="Permalink to &quot;☁️ 계정 클라우드 자동 동기화 (Auto Sync)&quot;">​</a></h3><ul><li>사용자가 변경한 위젯 배치와 크기는 브라우저 로컬 저장소뿐만 아니라 <strong>사용자 계정 DB에 자동으로 실시간 동기화</strong>됩니다.</li><li>다른 PC나 모바일 기기에서 로그인하더라도 내가 설정한 커스텀 레이아웃이 완벽하게 유지됩니다.</li><li>데스크톱, 태블릿, 모바일 등 접속 해상도에 맞춰 그리드 컬럼이 동적으로 반응합니다.</li></ul><h2 id="_2-제공-위젯-목록-14종" tabindex="-1">2. 제공 위젯 목록 (14종) <a class="header-anchor" href="#_2-제공-위젯-목록-14종" aria-label="Permalink to &quot;2. 제공 위젯 목록 (14종)&quot;">​</a></h2><p>IBS 대시보드는 비즈니스 목적에 따라 14종의 위젯을 제공합니다. (⭐️: 초기 기본 활성화 위젯)</p><h3 id="🎯-전사-협업-및-업무-관리-위젯" tabindex="-1">🎯 전사 협업 및 업무 관리 위젯 <a class="header-anchor" href="#🎯-전사-협업-및-업무-관리-위젯" aria-label="Permalink to &quot;🎯 전사 협업 및 업무 관리 위젯&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">위젯 이름</th><th style="text-align:left;">영문 ID</th><th style="text-align:center;">기본/최소 크기</th><th style="text-align:left;">주요 기능 및 연관 매뉴얼</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>내 업무</strong> ⭐️</td><td style="text-align:left;"><code>my-issue</code></td><td style="text-align:center;">$6 \\times 4$ ($6 \\times 3$)</td><td style="text-align:left;">본인에게 할당된 진행 중인 작업 목록 및 진척률 확인 $\\to$ <a href="/work-manage/issue.html">업무 관리</a></td></tr><tr><td style="text-align:left;"><strong>회의록</strong> ⭐️</td><td style="text-align:left;"><code>meeting-minutes</code></td><td style="text-align:center;">$6 \\times 4$ ($4 \\times 3$)</td><td style="text-align:left;">최근 회의의 아젠다, 결정 사항 및 액션아이템 요약 $\\to$ <a href="/work-manage/meeting.html">회의록 관리</a></td></tr><tr><td style="text-align:left;"><strong>이슈 트래커</strong> ⭐️</td><td style="text-align:left;"><code>issue-tracker</code></td><td style="text-align:center;">$6 \\times 4$ ($4 \\times 3$)</td><td style="text-align:left;">전체 업무(이슈)의 유형별/상태별 진행 통계 차트 $\\to$ <a href="/work-manage/roadmap.html">로드맵</a></td></tr><tr><td style="text-align:left;"><strong>캘린더</strong></td><td style="text-align:left;"><code>calendar</code></td><td style="text-align:center;">$12 \\times 5$ ($6 \\times 4$)</td><td style="text-align:left;">프로젝트 주요 마일스톤, 업무 마감일, 회의 일정 시각화 $\\to$ <a href="/work-manage/calendar.html">캘린더</a></td></tr><tr><td style="text-align:left;"><strong>활동 피드</strong></td><td style="text-align:left;"><code>activity-feed</code></td><td style="text-align:center;">$3 \\times 4$ ($3 \\times 3$)</td><td style="text-align:left;">시스템 전반에서 발생한 실시간 변경 및 작업 로그 타임라인 $\\to$ <a href="/work-manage/activity.html">실행내역</a></td></tr></tbody></table><h3 id="🏢-프로젝트-및-분양·수납-위젯" tabindex="-1">🏢 프로젝트 및 분양·수납 위젯 <a class="header-anchor" href="#🏢-프로젝트-및-분양·수납-위젯" aria-label="Permalink to &quot;🏢 프로젝트 및 분양·수납 위젯&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">위젯 이름</th><th style="text-align:left;">영문 ID</th><th style="text-align:center;">기본/최소 크기</th><th style="text-align:left;">주요 기능 및 연관 매뉴얼</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>프로젝트 현황</strong></td><td style="text-align:left;"><code>project-status</code></td><td style="text-align:center;">$6 \\times 4$ ($4 \\times 3$)</td><td style="text-align:left;">참여 중인 프로젝트의 기본 정보, 기간, 전체 진행 상태 요약 $\\to$ <a href="/project/">프로젝트 등록</a></td></tr><tr><td style="text-align:left;"><strong>프로젝트별 분양 계약률</strong></td><td style="text-align:left;"><code>contract-status</code></td><td style="text-align:center;">$6 \\times 4$ ($4 \\times 3$)</td><td style="text-align:left;">프로젝트별 분양 완료율 및 계약 상태 요약 차트 $\\to$ <a href="/contract/status.html">동호배치 현황</a></td></tr><tr><td style="text-align:left;"><strong>최근 등록 계약</strong></td><td style="text-align:left;"><code>contract-log</code></td><td style="text-align:center;">$6 \\times 4$ ($4 \\times 3$)</td><td style="text-align:left;">최근 체결된 분양 계약 및 입금 트랜잭션 실시간 목록 $\\to$ <a href="/contract/">계약 관리</a></td></tr><tr><td style="text-align:left;"><strong>프로젝트별 수납 현황</strong></td><td style="text-align:left;"><code>financial-status</code></td><td style="text-align:center;">$6 \\times 4$ ($4 \\times 3$)</td><td style="text-align:left;">회차별 수납액, 미납액 및 재무 흐름 그래프 $\\to$ <a href="/payment/status.html">수납 현황</a></td></tr><tr><td style="text-align:left;"><strong>최근 문서 목록</strong></td><td style="text-align:left;"><code>document-list</code></td><td style="text-align:center;">$6 \\times 4$ ($4 \\times 3$)</td><td style="text-align:left;">프로젝트 및 본사에서 최근 공유된 공식 문서 목록 $\\to$ <a href="/document/">문서 관리</a></td></tr></tbody></table><h3 id="⚡-정보-포털-및-빠른-작업-위젯" tabindex="-1">⚡ 정보 포털 및 빠른 작업 위젯 <a class="header-anchor" href="#⚡-정보-포털-및-빠른-작업-위젯" aria-label="Permalink to &quot;⚡ 정보 포털 및 빠른 작업 위젯&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">위젯 이름</th><th style="text-align:left;">영문 ID</th><th style="text-align:center;">기본/최소 크기</th><th style="text-align:left;">주요 기능 및 상세 안내</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>오늘의 한마디</strong> ⭐️</td><td style="text-align:left;"><code>wise-word</code></td><td style="text-align:center;">$12 \\times 2$ ($4 \\times 2$)</td><td style="text-align:left;">매일 새로운 비즈니스 격언 및 동기부여 메시지 표출</td></tr><tr><td style="text-align:left;"><strong>공지 목록</strong> ⭐️</td><td style="text-align:left;"><code>notice-list</code></td><td style="text-align:center;">$6 \\times 4$ ($6 \\times 3$)</td><td style="text-align:left;">전사 및 프로젝트별 최신 공지사항 목록 $\\to$ <a href="/work-manage/news.html">공지 관리</a></td></tr><tr><td style="text-align:left;"><strong>빠른 작업</strong></td><td style="text-align:left;"><code>quick-actions</code></td><td style="text-align:center;">$3 \\times 4$ ($3 \\times 2$)</td><td style="text-align:left;">자주 쓰는 8가지 핵심 메뉴(거래등록, 업무등록, 계약등록 등) 즉시 실행</td></tr><tr><td style="text-align:left;"><strong>메인 슬라이드</strong></td><td style="text-align:left;"><code>main-carousel</code></td><td style="text-align:center;">$12 \\times 5$ ($6 \\times 3$)</td><td style="text-align:left;">주요 사내 배너 및 비주얼 이미지 슬라이드 뷰어</td></tr></tbody></table><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>빠른 작업(Quick Actions) 8대 단축 버튼</strong>: <code>거래 등록</code>, <code>업무 등록</code>, <code>계약 등록</code>, <code>일정 보기(캘린더)</code>, <code>납부 내역</code>, <code>업무실행내역</code>, <code>공지 작성</code>, <code>새 워크스페이스 추가</code>를 원클릭으로 호출할 수 있습니다.</p></div><h2 id="_3-직무별-권장-위젯-배치-가이드" tabindex="-1">3. 직무별 권장 위젯 배치 가이드 <a class="header-anchor" href="#_3-직무별-권장-위젯-배치-가이드" aria-label="Permalink to &quot;3. 직무별 권장 위젯 배치 가이드&quot;">​</a></h2><ul><li><strong>프로젝트 총괄 (PM / 사업관리자)</strong>: <ul><li><strong>상단</strong>: <code>프로젝트 현황</code>, <code>이슈 트래커</code></li><li><strong>중단</strong>: <code>캘린더</code>, <code>회의록</code>, <code>활동 피드</code></li><li><strong>하단</strong>: <code>공지 목록</code>, <code>최근 문서 목록</code></li></ul></li><li><strong>영업 / 분양 / 수납 담당자</strong>: <ul><li><strong>상단</strong>: <code>프로젝트별 분양 계약률</code>, <code>프로젝트별 수납 현황</code></li><li><strong>중단</strong>: <code>최근 등록 계약</code>, <code>내 업무</code>, <code>빠른 작업</code></li><li><strong>하단</strong>: <code>공지 목록</code>, <code>캘린더</code></li></ul></li><li><strong>일반 실무자 / 팀원</strong>: <ul><li><strong>상단</strong>: <code>오늘의 한마디</code>, <code>내 업무</code>, <code>빠른 작업</code></li><li><strong>중단</strong>: <code>회의록</code>, <code>캘린더</code>, <code>공지 목록</code></li><li><strong>하단</strong>: <code>활동 피드</code></li></ul></li></ul>',20)])])}const x=e(d,[["render",s]]);export{f as __pageData,x as default};
